// Full graph6 stream audit. Reads uncompressed records from stdin. Counts charts, not records with a chart.
use std::io::{self,BufRead};
fn tr(s:usize,a:usize,b:usize)->usize {if (s>>a^s>>b)&1!=0{s^(1<<a)^(1<<b)}else{s}}
fn main(){let mut actions=vec![];for f in 0..7 {fn pairs(v:Vec<usize>,p:Vec<(usize,usize)>,out:&mut Vec<Vec<(usize,usize)>>){if v.is_empty(){out.push(p);return}for j in 1..v.len(){let mut q=p.clone();q.push((v[0],v[j]));pairs(v.iter().copied().filter(|&i|i!=v[0]&&i!=v[j]).collect(),q,out)}}pairs((0..7).filter(|&i|i!=f).collect(),vec![],&mut actions)}let mut counts=[0u64;5];let mut first=[0u64;2];for line in io::stdin().lock().lines(){let l=line.unwrap();let l=l.as_bytes();assert_eq!(l[0],90);counts[0]+=1;let mut h=[0u32;27];let mut p=0;for j in 0..27{for i in 0..j{if (l[1+p/6]-63)>>(5-p%6)&1!=0{h[i]|=1<<j;h[j]|=1<<i}p+=1}}for i in 0..27{if h[i].count_ones()!=7{continue}counts[1]+=1;let v:Vec<_>=(0..27).filter(|j|h[i]>>j&1!=0).collect();let mut s=[0u8;128];let mut fp=[0u64;7];for j in 0..27{if j==i||h[i]>>j&1!=0{continue}let mut m=0usize;for (k,&x) in v.iter().enumerate(){m|=(((h[j]>>x)&1)as usize)<<k}s[m]+=1;for k in 0..7{if m>>k&1!=0{fp[k]+=1u64<<(5*m.count_ones())}}}let mut sorted=fp;sorted.sort_unstable();let mut odd=0;let mut k=0;while k<7{let a=k;k+=1;while k<7&&sorted[a]==sorted[k]{k+=1}odd+=(k-a)%2}if odd!=1{continue}counts[2]+=1;let mut passed=false;let mut frame=false;let inv=|a:(usize,usize),b:(usize,usize)|(0..128).all(|m|s[m]==s[tr(tr(m,a.0,a.1),b.0,b.1)]);for p in &actions{if !p.iter().all(|&(a,b)|fp[a]==fp[b])||!inv(p[0],p[1])||!inv(p[0],p[2]){continue}passed=true;for j in 0..3{let(a,b)=p[j];let(c,d)=p[(j+1)%3];if inv((a,c),(b,d))||inv((a,d),(b,c)){frame=true;break}}if frame{break}}if passed{counts[3]+=1;if first[0]==0{first[0]=counts[0]}}if frame{counts[4]+=1;if first[1]==0{first[1]=counts[0]}}}}println!("records charts profiles translations frames: {:?}; first record V4/D8: {:?}",counts,first)}
